arguments.command:
cd /testbed && source /opt/miniconda3/bin/activate testbed && python -c "
import os
import sys

# Check if there's a wrapper in the PATH
path_dirs = os.environ.get('PATH', '').split(':')
for path_dir in path_dirs:
    if 'openssl' in os.listdir(path_dir):
        print(f'Found openssl in {path_dir}')
        for f in os.listdir(path_dir):
            if 'openssl' in f.lower():
                print(f'  {f}')
                if os.path.isfile(os.path.join(path_dir, f)):
                    stat = os.stat(os.path.join(path_dir, f))
                    print(f'    Type: {stat.st_mode}')
                    print(f'    Size: {stat.st_size}')
"

